#include <stdio.h>
#include <stdlib.h>

static long memo[91];
static char computed[91];

static long fib(int n) {
    if (computed[n])
        return memo[n];
    if (n == 0) {
        memo[0] = 0;
    } else if (n == 1) {
        memo[1] = 1;
    } else {
        memo[n] = fib(n - 1) + fib(n - 2);
    }
    computed[n] = 1;
    return memo[n];
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long val = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (val < 0) {
        puts("NEGATIVE");
        return 0;
    }
    if (val > 90) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long result = fib((int)val);
    printf("%lld\n", result);
    return 0;
}
